contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 reqAmount, uint256 reqInterest, uint256 loanToCollateral, uint256 duration) public {
        require(reqAmount > 0 && reqAmount <= 100);
        require(reqInterest <= 1e18);
        require(loanToCollateral > 0 && loanToCollateral <= 100);
        require(duration > 0 && duration <= 365 days);

        uint256 reqID = c.requestLoan(reqAmount, reqInterest, loanToCollateral, duration); if (__ESBMC_reverted()) return;
        require(c.isActive(reqID));

        c.clearRequest(reqID, true, false); if (__ESBMC_reverted()) return;
        bool stillActive = c.isActive(reqID); if (__ESBMC_reverted()) return;

        assert(!stillActive);
    }
}

