// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqAmount, uint256 reqInterest, uint256 loanToCollateral, uint256 duration) internal {
        reqAmount = bound(reqAmount, 1, 100);
        vm.assume(reqInterest <= 1e18);
        loanToCollateral = bound(loanToCollateral, 1, 100);
        duration = bound(duration, 1, 365);
        uint256 reqID;
        try c.requestLoan(reqAmount, reqInterest, loanToCollateral, duration) returns (uint256 __r) { reqID = __r; } catch { return; }
        vm.assume(c.isActive(reqID));
        try c.clearRequest(reqID, true, false) {} catch { return; }
        bool stillActive;
        try c.isActive(reqID) returns (bool __r) { stillActive = __r; } catch { return; }
        assertTrue(!stillActive);
    }

    function testFuzz_run(uint256 reqAmount, uint256 reqInterest, uint256 loanToCollateral, uint256 duration) public {
        _run(reqAmount, reqInterest, loanToCollateral, duration);
    }

    receive() external payable {}
}
